1	// Catalogue search for the planner's add-one-by-one flow: plain-text matching
2	// plus facet filters (genre, subgenre, accessibility, age limit, price) over
3	// the rehydrated show records.
4	//
5	// Pure — no DOM, no fetch. plan.js feeds it the catalogue from buildIndex and
6	// renders the results; the unit tests live in __tests__/search.test.mjs.
7	//
8	// Two facets read fields that may simply be absent for a show:
9	//   - `show.accessibility` — an array of enum strings (the API's per-show
10	//     `accessibility` list). Not shipped by the scraper yet.
11	//   - `show.priceMin` — the cheapest band in pounds, from the price cache
12	//     (scraper/fetch_prices.py). Present for free shows and for anything the
13	//     price pass has reached; null otherwise, and null is *not* £0.
14	// Absence means unknown, and an active filter on these facets excludes
15	// unknowns — a filter must never claim a show matches on data it doesn't
16	// have. catalogueFacets() tells the UI whether either facet has any data at
17	// all, so it can disable the control instead of offering a filter that
18	// silently matches nothing.
19	
20	// Age-restriction enum → the minimum age it admits. Keys are the full
21	// ageRestrictions value set in data/venues.json.
22	export const AGE_LIMIT_YEARS = {
23	  ZERO: 0,
24	  THREE: 3,
25	  FIVE: 5,
26	  EIGHT: 8,
27	  TWELVE: 12,
28	  FOURTEEN: 14,
29	  SIXTEEN: 16,
30	  EIGHTEEN: 18,
31	};
32	
33	/** Minimum admitted age for a show, or null when unknown. */
34	export function ageLimitYears(show) {
35	  const v = AGE_LIMIT_YEARS[show && show.ageRestriction];
36	  return v === undefined ? null : v;
37	}
38	
39	// The price vocabulary is shared with the Now page rather than defined twice —
40	// two pages disagreeing about what a show costs is worse than either being
41	// wrong. Re-exported so this module stays the planner's one search import.
42	import { showPrice } from "../../shared/price.js";
43	
44	export { showPrice };
45	
46	/** The show's declared accessibility options ([] when none / unknown). */
47	export function showAccessibility(show) {
48	  const list = show && show.accessibility;
49	  return Array.isArray(list) ? list : [];
50	}
51	
52	/**
53	 * One pass over the catalogue: which optional facets carry any data, and the
54	 * value set for the data-driven ones.
55	 *
56	 * @returns {{accessibility: string[], hasPrice: boolean}} accessibility is the
57	 *   sorted union of declared options (empty = the facet has no data yet).
58	 */
59	export function catalogueFacets(shows) {
60	  const access = new Set();
61	  let hasPrice = false;
62	  for (const show of shows || []) {
63	    for (const a of showAccessibility(show)) access.add(a);
64	    // A *paid* show with a known amount is what makes the "up to £X" caps
65	    // worth offering. Free shows alone don't: every cap would return exactly
66	    // the free list, which the Free option already gives.
67	    if (!hasPrice && showPrice(show) > 0) hasPrice = true;
68	  }
69	  return { accessibility: [...access].sort(), hasPrice };
70	}
71	
72	/**
73	 * @typedef {object} SearchFilters
74	 * @property {string|string[]} [genre]         genre label(s); several = any of them
75	 * @property {string|string[]} [subgenre]      subgenre label(s) (matched in show.subgenres)
76	 * @property {string|string[]} [accessibility] enum value(s) the show must declare
77	 * @property {string|string[]} [venue]         venue code(s) — `show.venue`, so every
78	 *                                    room of a venue counts as that venue
79	 * @property {number} [maxAge]        highest admitted minimum age (inclusive):
80	 *                                    2 excludes nothing rated above 2; unknown excluded
81	 * @property {"free"|number} [price]  "free", or a cap in pounds (inclusive);
82	 *                                    unknown-price shows excluded either way
83	 *
84	 * The four label facets take one value or many. Many are OR'd — the UI offers
85	 * them as checkbox lists, where ticking a second box widens the search — while
86	 * separate facets are AND'd.
87	 */
88	
89	/** A facet's values as a list: "" / undefined / [] all mean "not set". */
90	function facetValues(v) {
91	  if (Array.isArray(v)) return v.filter(Boolean);
92	  return v ? [v] : [];
93	}
94	
95	/** True when any filter field is set (i.e. filtering would narrow the list). */
96	export function hasActiveFilters(filters) {
97	  const f = filters || {};
98	  return (
99	    facetValues(f.genre).length > 0 ||
100	    facetValues(f.subgenre).length > 0 ||
101	    facetValues(f.accessibility).length > 0 ||
102	    facetValues(f.venue).length > 0 ||
103	    typeof f.maxAge === "number" ||
104	    f.price === "free" ||
105	    typeof f.price === "number"
106	  );
107	}
108	
109	/** The shows passing every set filter (see SearchFilters for the semantics). */
110	export function filterShows(shows, filters) {
111	  const f = filters || {};
112	  const genres = facetValues(f.genre);
113	  const subgenres = facetValues(f.subgenre);
114	  const access = facetValues(f.accessibility);
115	  const venues = facetValues(f.venue);
116	  return (shows || []).filter((show) => {
117	    if (genres.length && !genres.includes(show.genre)) return false;
118	    if (subgenres.length && !subgenres.some((s) => (show.subgenres || []).includes(s))) return false;
119	    if (access.length && !access.some((a) => showAccessibility(show).includes(a))) return false;
120	    if (venues.length && !venues.includes(String(show.venue))) return false;
121	    if (typeof f.maxAge === "number") {
122	      const age = ageLimitYears(show);
123	      if (age === null || age > f.maxAge) return false;
124	    }
125	    if (f.price === "free") {
126	      if (showPrice(show) !== 0) return false;
127	    } else if (typeof f.price === "number") {
128	      const price = showPrice(show);
129	      if (price === null || price > f.price) return false;
130	    }
131	    return true;
132	  });
133	}
134	
135	// Case- and accent-insensitive matching: "cafe" finds "Café".
136	function fold(s) {
137	  return String(s || "")
138	    .toLowerCase()
139	    .normalize("NFD")
140	    .replace(/[\u0300-\u036f]/g, "");
141	}
142	
143	// Escape a string for use inside a RegExp (word-boundary probes below).
144	function reEscape(s) {
145	  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
146	}
147	
148	/** What a show's searchable description text is, when the caller doesn't say.
149	 *  The one-line blurb travels in the catalogue itself, so description search
150	 *  works from the first byte; a caller with the fuller descriptions sidecar
151	 *  loaded passes its own `describe` and the same search simply reaches
152	 *  further. */
153	const defaultDescribe = (show) => show.blurb || "";
154	
155	/**
156	 * Rank one show against a folded query. 0 = no match. Title matches outrank
157	 * company/venue matches, which outrank a hit found only in the description;
158	 * within the title: prefix > word start > anywhere. Multi-word queries must
159	 * land every word somewhere in the text considered.
160	 */
161	function scoreShow(show, foldedQuery, tokens, describe) {
162	  const title = fold(show.title);
163	  const rest = fold(`${show.company || ""} ${show.venueName || ""}`);
164	  const hay = `${title} ${rest}`;
165	
166	  if (!tokens.every((t) => hay.includes(t))) {
167	    // Nothing in the name, company or venue — try the description before
168	    // giving up. A show found only this way ranks below every named match, so
169	    // description hits extend the tail of the results rather than reordering
170	    // the head someone was already looking at.
171	    const desc = fold(describe(show) || "");
172	    if (!desc) return 0;
173	    const deep = `${hay} ${desc}`;
174	    return tokens.every((t) => deep.includes(t)) ? 0.5 : 0;
175	  }
176	
177	  if (title.startsWith(foldedQuery)) return 4;
178	  if (new RegExp(`\\b${reEscape(foldedQuery)}`).test(title)) return 3;
179	  if (title.includes(foldedQuery)) return 2;
180	  return 1;
181	}
182	
183	/**
184	 * The main entry: filter, then match the query, then rank.
185	 *
186	 * - Empty query + no active filters → nothing (the UI shows no popup).
187	 * - Empty query + filters → the whole filtered list, A→Z (browse by facet).
188	 * - With a query: ranked matches (see scoreShow), ties A→Z.
189	 *
190	 * @param {object[]} shows        the catalogue (e.g. [...index.values()])
191	 * @param {string} query          raw user text
192	 * @param {SearchFilters} filters
193	 * @param {{limit?: number, describe?: (show: object) => string}} [opts]
194	 *   `describe` supplies the description text to search for a show; it defaults
195	 *   to the catalogue's own one-line blurb. The planner passes a function that
196	 *   prefers the fuller descriptions sidecar once it has downloaded, so the same
197	 *   query reaches deeper the longer the page has been open.
198	 * @returns {{results: object[], total: number}} results capped at limit;
199	 *   total is the uncapped match count (for a "showing X of Y" footer)
200	 */
201	export function searchShows(shows, query, filters, { limit = 30, describe = defaultDescribe } = {}) {
202	  const foldedQuery = fold(query).trim().replace(/\s+/g, " ");
203	  const tokens = foldedQuery ? foldedQuery.split(" ") : [];
204	  if (tokens.length === 0 && !hasActiveFilters(filters)) return { results: [], total: 0 };
205	
206	  const pool = filterShows(shows, filters);
207	  const byTitle = (a, b) => fold(a.title).localeCompare(fold(b.title));
208	
209	  if (tokens.length === 0) {
210	    const all = [...pool].sort(byTitle);
211	    return { results: all.slice(0, limit), total: all.length };
212	  }
213	
214	  const scored = [];
215	  for (const show of pool) {
216	    const score = scoreShow(show, foldedQuery, tokens, describe);
217	    if (score > 0) scored.push({ show, score });
218	  }
219	  scored.sort((a, b) => b.score - a.score || byTitle(a.show, b.show));
220	  return { results: scored.slice(0, limit).map((s) => s.show), total: scored.length };
221	}
222	
223	// --- Facet suggestions ("you typed a venue, not a show") -------------------
224	//
225	// A query is often the name of a *category* rather than a show: "pleasance",
226	// "cabaret", "stand-up". Those deserve an answer the show list can't give — set
227	// the matching filter and see the whole slate — so the UI offers them as rows
228	// above the show hits, and picking one ticks that facet.
229	
230	/**
231	 * The venues that actually have shows, A→Z by name: `{value, label, count}`,
232	 * where value is the venue code (`show.venue`) and count is its show tally —
233	 * the tie-break that puts a hub above its satellite in a suggestion list.
234	 */
235	export function catalogueVenues(shows, venueMap) {
236	  const counts = new Map();
237	  for (const show of shows || []) {
238	    const code = show && show.venue != null ? String(show.venue) : "";
239	    if (!code) continue;
240	    counts.set(code, (counts.get(code) || 0) + 1);
241	  }
242	  const out = [];
243	  for (const [code, count] of counts) {
244	    const entry = (venueMap || {})[code];
245	    const label = (entry && entry.name) || null;
246	    if (label) out.push({ value: code, label, count });
247	  }
248	  out.sort((a, b) => fold(a.label).localeCompare(fold(b.label)));
249	  return out;
250	}
251	
252	// A label match is worth ranking three ways, same idea as scoreShow: the query
253	// starts the name > starts a word in it > lands anywhere in it.
254	function scoreLabel(label, foldedQuery) {
255	  const l = fold(label);
256	  if (l.startsWith(foldedQuery)) return 3;
257	  if (new RegExp(`\\b${reEscape(foldedQuery)}`).test(l)) return 2;
258	  if (l.includes(foldedQuery)) return 1;
259	  return 0;
260	}
261	
262	// Which facet wins a score tie — the broader the category, the higher it sits.
263	const FACET_ORDER = ["genre", "subgenre", "venue"];
264	
265	/**
266	 * The genres, subgenres and venues whose names the query matches, best first.
267	 *
268	 * @param {string} query raw user text (under 2 characters yields nothing — a
269	 *   single letter matches half the programme and would bury the show hits)
270	 * @param {{genres?: string[], subgenres?: string[],
271	 *          venues?: {value: string, label: string, count?: number}[]}} catalogue
272	 *   the value sets to offer; venues carry a code (`value`) distinct from their
273	 *   display name, and an optional show `count` that breaks score ties (so
274	 *   "pleasance" offers the Courtyard before a one-room outpost)
275	 * @param {{limit?: number}} [opts]
276	 * @returns {{kind: "genre"|"subgenre"|"venue", value: string, label: string}[]}
277	 */
278	export function matchFacets(query, catalogue, { limit = 4 } = {}) {
279	  const foldedQuery = fold(query).trim().replace(/\s+/g, " ");
280	  if (foldedQuery.length < 2) return [];
281	  const c = catalogue || {};
282	  const pools = [
283	    ["genre", (c.genres || []).map((v) => ({ value: v, label: v }))],
284	    ["subgenre", (c.subgenres || []).map((v) => ({ value: v, label: v }))],
285	    ["venue", c.venues || []],
286	  ];
287	
288	  const hits = [];
289	  for (const [kind, values] of pools) {
290	    for (const { value, label, count } of values) {
291	      const score = scoreLabel(label, foldedQuery);
292	      if (score > 0) hits.push({ kind, value, label, score, count: count || 0 });
293	    }
294	  }
295	  hits.sort(
296	    (a, b) =>
297	      b.score - a.score ||
298	      FACET_ORDER.indexOf(a.kind) - FACET_ORDER.indexOf(b.kind) ||
299	      b.count - a.count ||
300	      fold(a.label).localeCompare(fold(b.label))
301	  );
302	  return hits.slice(0, limit).map(({ kind, value, label }) => ({ kind, value, label }));
303	}
