1747	// --- Show search: build / top up the grid one show at a time ---------------
1748	//
1749	// One component (#showSearch) in one place — under the board body, whichever
1750	// state the board is in — so building a grid from scratch and topping up a full
1751	// one are the same gesture in the same spot. Results render as one line per
1752	// show; the star on the left adds the show to the working favourites through the
1753	// same path an upload takes (applyFavourites), so persistence, matching and the
1754	// live re-plan all follow. When the query names a genre, subgenre or venue, those
1755	// come first as category rows that set the matching filter (see renderResultRows).
1756	// The matching/filtering itself is pure and lives in ./lib/search.js.
1757	
1758	const SEARCH_LIMIT = 30;
1759	const FACET_SUGGESTION_LIMIT = 4;
1760	
1761	const searchUi = {
1762	  active: -1, // index of the keyboard-highlighted row, -1 = none
1763	  // The popup's rows, in display order: the category suggestions first, then the
1764	  // show hits. One list so arrow keys walk both.
1765	  rows: [],
1766	  total: 0,
1767	  shown: 0,
1768	  debounce: null,
1769	  venues: [], // [{value: code, label: name}] — filled once the catalogue lands
1770	  // One entry per facet: a Set for the multi-select lists, a string ("" = not
1771	  // set) for the two single-answer ones.
1772	  filters: {
1773	    genre: new Set(),
1774	    subgenre: new Set(),
1775	    accessibility: new Set(),
1776	    venue: new Set(),
1777	    age: "",
1778	    price: "",
1779	  },
1780	};
1781	
1782	/** "AUDIO_DESCRIPTION" → "Audio description". */
1783	function humanizeEnum(v) {
1784	  const s = String(v).replace(/_/g, " ").toLowerCase();
1785	  return s.charAt(0).toUpperCase() + s.slice(1);
1786	}
1787	
1788	/* The six search facets, each rendered as a chip that drops a panel of
1789	 * options with a grey count of how many shows it would give you.
1790	 *   multi    — a checkbox list (ticking a second box widens the search); the
1791	 *              single-answer ones (age, price) are radios.
1792	 *   values   — the option list, once the catalogue is in.
1793	 *   valuesOf — a show's own value(s) for the facet, when it has a fixed set we
1794	 *              can tally in one pass. Facets without it (the "up to X" caps)
1795	 *              are counted by testing each option with `matches`.
1796	 *   label    — how a value is written for people (venue codes, enums, caps).
1797	 *   find     — the facet's panel gets a type-to-narrow box over a long list.
1798	 */
1799	const SEARCH_FACETS = [
1800	  {
1801	    key: "genre",
1802	    id: "Genre",
1803	    multi: true,
1804	    any: "Any genre",
1805	    noun: "genres",
1806	    values: () => [...(state.lookups.genres || [])].sort(),
1807	    valuesOf: (show) => [show.genre].filter(Boolean),
1808	  },
1809	  {
1810	    key: "subgenre",
1811	    id: "Subgenre",
1812	    multi: true,
1813	    any: "Any subgenre",
1814	    noun: "subgenres",
1815	    values: () => [...(state.lookups.subgenres || [])].sort(),
1816	    valuesOf: (show) => show.subgenres || [],
1817	  },
1818	  {
1819	    // Keyed on the venue *code*, so picking "Pleasance Courtyard" takes every
1820	    // room in it. 300-odd options, hence the find box.
1821	    key: "venue",
1822	    id: "Venue",
1823	    multi: true,
1824	    any: "Any venue",
1825	    noun: "venues",
1826	    find: true,
1827	    values: () => searchUi.venues.map((v) => v.value),
1828	    label: (v) => venueLabel(v),
1829	    valuesOf: (show) => (show.venue != null ? [String(show.venue)] : []),
1830	  },
1831	  {
1832	    key: "accessibility",
1833	    id: "Access",
1834	    multi: true,
1835	    any: "Any accessibility",
1836	    noun: "access needs",
1837	    label: humanizeEnum,
1838	    values: () => state.facets.accessibility,
1839	    valuesOf: showAccessibility,
1840	    // The scraper doesn't ship this field yet (see lib/search.js). A control
1841	    // that could only ever match nothing is presented as coming soon rather
1842	    // than left to look broken.
1843	    unavailable: () => state.facets.accessibility.length === 0,
1844	    unavailableHint: "Accessibility data hasn't landed in our catalogue yet — coming soon",
1845	  },
1846	  {
1847	    key: "age",
1848	    id: "Age",
1849	    multi: false,
1850	    any: "Any age limit",
1851	    values: () => ["0", "3", "5", "8", "12", "14", "16"],
1852	    label: (v) => (v === "0" ? "0+ only" : `Up to ${v}+`),
1853	    matches: (show, v) => {
1854	      const age = ageLimitYears(show);
1855	      return age !== null && age <= Number(v);
1856	    },
1857	  },
1858	  {
1859	    key: "price",
1860	    id: "Price",
1861	    multi: false,
1862	    any: "Any price",
1863	    money: true,
1864	    // The same ladder the Now page's "$" chip offers, minus its "any" option —
1865	    // this facet expresses "any" as no radio chosen. Sharing it is what keeps
1866	    // the two pages from quoting different budgets for the same catalogue.
1867	    values: () => PRICE_OPTIONS.filter((o) => o.value !== "any").map((o) => o.value),
1868	    label: (v) => (PRICE_OPTIONS.find((o) => o.value === v) || {}).label || v,
1869	    matches: (show, v) => matchesPrice(show, v),
1870	    // The price cache is fetched once while the festival keeps adding shows, so
1871	    // some shows have no amount; the caps stay offered as long as *any* paid
1872	    // show is priced, and simply exclude the unknowns (shared/price.js).
1873	    optionUnavailable: (v) => v !== "free" && !state.facets.hasPrice,
1874	    optionUnavailableHint: "No ticket prices scraped yet — “Free” already works",
1875	  },
1876	];
1877	
1878	const facetById = (key) => SEARCH_FACETS.find((f) => f.key === key);
1879	
1880	/** The chosen value(s) of a facet, as a list. */
1881	function facetChosen(facet) {
1882	  const v = searchUi.filters[facet.key];
1883	  return facet.multi ? [...v] : v ? [v] : [];
1884	}
1885	
1886	/** Is every option this facet offers already ticked? (Never true for the
1887	 *  single-answer facets, which offer one radio at a time.) */
1888	function allOptionsChosen(facet) {
1889	  if (!facet.multi) return false;
1890	  const values = facet.values();
1891	  return values.length > 0 && values.every((v) => searchUi.filters[facet.key].has(v));
1892	}
1893	
1894	/** Read the facet state into a lib/search.js-shaped filters object. */
1895	function currentSearchFilters() {
1896	  const f = searchUi.filters;
1897	  const filters = {
1898	    genre: [...f.genre],
1899	    subgenre: [...f.subgenre],
1900	    accessibility: [...f.accessibility],
1901	    venue: [...f.venue],
1902	  };
1903	  if (f.age !== "") filters.maxAge = Number(f.age);
1904	  if (f.price === "free") filters.price = "free";
1905	  else if (f.price !== "") filters.price = Number(f.price);
1906	  return filters;
1907	}
1908	
1909	/** The same object with one facet left out — the pool a facet's own option
1910	 *  counts are measured against, so a count answers "how many shows would
1911	 *  ticking this give me". */
1912	function searchFiltersExcept(key) {
1913	  const filters = currentSearchFilters();
1914	  if (key === "age") delete filters.maxAge;
1915	  else if (key === "price") delete filters.price;
1916	  else filters[key] = [];
1917	  return filters;
1918	}
1919	
1920	/** How many catalogue shows each of a facet's options would match. */
1921	function facetOptionCounts(facet, values) {
1922	  const pool = filterShows(state.catalogue, searchFiltersExcept(facet.key));
1923	  const counts = new Map(values.map((v) => [v, 0]));
1924	  if (facet.valuesOf) {
1925	    for (const show of pool) {
1926	      for (const v of facet.valuesOf(show)) {
1927	        if (counts.has(v)) counts.set(v, counts.get(v) + 1);
1928	      }
1929	    }
1930	  } else {
1931	    for (const show of pool) {
1932	      for (const v of values) if (facet.matches(show, v)) counts.set(v, counts.get(v) + 1);
1933	    }
1934	  }
1935	  return counts;
1936	}
1937	
1938	/** Render one facet's option rows (checkboxes, or radios for the single-answer
1939	 *  facets), each with its grey show count. */
1940	function buildFacetPanel(facet) {
1941	  const wrap = $(`ssf${facet.id}Options`);
1942	  if (!wrap) return;
1943	  const values = facet.values();
1944	  wrap.innerHTML = "";
1945	  if (!values.length) {
1946	    wrap.innerHTML = `<p class="panel-note">${escapeHtml(facet.unavailableHint || "Nothing to filter by yet.")}</p>`;
1947	    return;
1948	  }
1949	  const counts = facetOptionCounts(facet, values);
1950	  const chosen = new Set(facetChosen(facet));
1951	  for (const v of values) {
1952	    const n = counts.get(v) || 0;
1953	    const off = facet.optionUnavailable ? facet.optionUnavailable(v) : false;
1954	    const row = document.createElement("label");
1955	    row.className = "panel-option" + (n === 0 || off ? " is-empty" : "");
1956	    if (off && facet.optionUnavailableHint) row.title = facet.optionUnavailableHint;
1957	    row.innerHTML =
1958	      `<input type="${facet.multi ? "checkbox" : "radio"}" name="ssf-${facet.key}"` +
1959	      ` value="${escapeHtml(v)}"${chosen.has(v) ? " checked" : ""}${off ? " disabled" : ""} />` +
1960	      `<span>${escapeHtml(facet.label ? facet.label(v) : v)}</span>` +
1961	      // An option we can't actually answer for gets an em dash, not a count
1962	      // that would read as a real (and wrong) number of matches.
1963	      (off
1964	        ? '<span class="opt-count" aria-label="no data yet">&mdash;</span>'
1965	        : `<span class="opt-count" aria-label="${n} ${n === 1 ? "show" : "shows"}">${n}</span>`);
1966	    const input = row.querySelector("input");
1967	    input.addEventListener("change", () => {
1968	      if (facet.multi) {
1969	        if (input.checked) searchUi.filters[facet.key].add(v);
1970	        else searchUi.filters[facet.key].delete(v);
1971	      } else {
1972	        // A radio can't be un-picked by clicking it — "everything!" beside the
1973	        // question is the way back to "any".
1974	        searchUi.filters[facet.key] = v;
1975	      }
1976	      onSearchFilterChange();
1977	    });
1978	    wrap.appendChild(row);
1979	  }
1980	}
1981	
1982	/** Rebuild every facet panel from scratch (once, when the catalogue lands). */
1983	function buildAllFacetPanels() {
1984	  for (const facet of SEARCH_FACETS) buildFacetPanel(facet);
1985	}
1986	
1987	/** Re-count every panel's rows in place. The option lists themselves never
1988	 *  change once the catalogue is in, and rebuilding them would drop focus
1989	 *  mid-click, so only the numbers and the ticks are rewritten. */
1990	function refreshFacetCounts() {
1991	  for (const facet of SEARCH_FACETS) {
1992	    const wrap = $(`ssf${facet.id}Options`);
1993	    if (!wrap) continue;
1994	    const rows = [...wrap.querySelectorAll(".panel-option")];
1995	    if (!rows.length) continue;
1996	    const counts = facetOptionCounts(facet, rows.map((r) => r.querySelector("input").value));
1997	    const chosen = new Set(facetChosen(facet));
1998	    for (const row of rows) {
1999	      const input = row.querySelector("input");
2000	      input.checked = chosen.has(input.value);
2001	      if (input.disabled) continue; // an "— no data yet" row keeps its dash
2002	      const n = counts.get(input.value) || 0;
2003	      const out = row.querySelector(".opt-count");
2004	      out.textContent = String(n);
2005	      out.setAttribute("aria-label", `${n} ${n === 1 ? "show" : "shows"}`);
2006	      row.classList.toggle("is-empty", n === 0);
2007	    }
2008	  }
2009	}
2010	
2011	/** A venue code as people read it ("Pleasance Courtyard"). */
2012	function venueLabel(code) {
2013	  const venues = (state.lookups && state.lookups.venues) || {};
2014	  const entry = venues[code];
2015	  return (entry && entry.name) || String(code);
2016	}
2017	
2018	/** Narrow a long option list to the rows matching what's typed in its find box. */
2019	function wireFacetFind(facet) {
2020	  const box = $(`ssf${facet.id}Find`);
2021	  const wrap = $(`ssf${facet.id}Options`);
2022	  if (!box || !wrap) return;
2023	  box.addEventListener("input", () => {
2024	    const q = box.value.trim().toLowerCase();
2025	    for (const row of wrap.querySelectorAll(".panel-option")) {
2026	      const text = (row.textContent || "").toLowerCase();
2027	      row.hidden = q !== "" && !text.includes(q);
2028	    }
2029	  });
2030	  // Typing in the box must not be read as "pick the first row" by the bar's
2031	  // keyboard handling, and Escape should clear the box before closing anything.
2032	  box.addEventListener("keydown", (e) => {
2033	    if (e.key === "Escape" && box.value !== "") {
2034	      e.stopPropagation();
2035	      box.value = "";
2036	      box.dispatchEvent(new Event("input"));
2037	    }
2038	  });
2039	}
2040	
