1	/* Non-show places — the "Not a show? Type a place" commitment.
2	 *
3	 * Everything here is pure (no DOM, no fetch): js/app.js does the fetching and
4	 * rendering, and js/__tests__/places.test.mjs exercises this module directly.
5	 *
6	 * Two jobs:
7	 *   1. Geocoding — build the Nominatim (OpenStreetMap's geocoder) search URL,
8	 *      bounded to Edinburgh, and normalize its results. Nominatim needs no API
9	 *      key, matching the site's Leaflet + OSM setup; its usage policy asks for
10	 *      an identifying Referer (the browser sends one) and ≤1 request/second
11	 *      (we only search on an explicit button press).
12	 *   2. Partner links — a booking link for the kinds of place people type
13	 *      (a restaurant table, train tickets, a hotel, an attraction), which
14	 *      becomes a referral link once the affiliate IDs below are filled in.
15	 */
16	
17	/* Bounding box for the geocoder: greater Edinburgh, Airport to Musselburgh.
18	 * Passed to Nominatim as a ranking bias and applied again client-side in
19	 * parsePlaces, so "Malmaison" can't resolve to the one in Newcastle.
20	 *
21	 * Deliberately NOT sent with `bounded=1`: probed against the live API
22	 * (2026-07-29), bounded restricts the search to amenity-tag matching inside
23	 * the box — "Waverley station" then returns the pub and café inside the
24	 * concourse but not Edinburgh Waverley itself, and "The Piemaker" returns
25	 * nothing. Unbounded search with the viewbox finds both; we drop any
26	 * out-of-box hits ourselves. */
27	export const EDINBURGH_VIEWBOX = { minLat: 55.87, maxLat: 56.0, minLng: -3.46, maxLng: -3.02 };
28	
29	/* Is a [lat, lng] inside the Edinburgh box above? */
30	export function inEdinburgh([lat, lng]) {
31	  const { minLat, maxLat, minLng, maxLng } = EDINBURGH_VIEWBOX;
32	  return lat >= minLat && lat <= maxLat && lng >= minLng && lng <= maxLng;
33	}
